# ==================== 语言检测函数 ====================

def _detect_system_language() -> str:
    """检测系统语言"""
    try:
        if platform.system() == "Windows":
            try:
                import ctypes
                lang_id = ctypes.windll.kernel32.GetUserDefaultUILanguage()
                lang_map = {
                    0x0804: "zh-CN", 0x0404: "zh-TW", 0x0409: "en-US",
                    0x0411: "ja-JP", 0x0412: "ko-KR", 0x040C: "fr-FR",
                    0x0407: "de-DE", 0x040A: "es-ES", 0x0416: "pt-BR",
                    0x0419: "ru-RU", 0x0401: "ar-SA", 0x0439: "hi-IN",
                }
                if lang_id in lang_map:
                    return lang_map[lang_id]
            except:
                pass
    except:
        pass
    return "zh-CN"  # 默认简体中文

# ==================== 核心国际化函数 ====================
# ==================== 增强版翻译系统（在线翻译 + 本地缓存） ====================

class OnlineTranslator:
    """在线翻译引擎 - 使用 Python 内置 urllib，无需额外安装"""
    
    @staticmethod
    def translate_mymemory(text: str, target_lang: str, source_lang: str = "zh") -> Optional[str]:
        """使用 MyMemory 翻译 - 纯内置库"""
        try:
            import urllib.request
            import urllib.parse
            
            url = f"https://api.mymemory.translated.net/get?q={urllib.parse.quote(text)}&langpair={source_lang}|{target_lang}"
            req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req, timeout=10) as response:
                data = json.loads(response.read().decode('utf-8'))
                if "responseData" in data:
                    return data["responseData"].get("translatedText")
        except:
            pass
        return None
    
    @staticmethod
    def translate_libre(text: str, target_lang: str, source_lang: str = "zh") -> Optional[str]:
        """使用 LibreTranslate 翻译 - 纯内置库"""
        try:
            import urllib.request
            
            data = json.dumps({
                "q": text,
                "source": source_lang,
                "target": target_lang,
                "format": "text"
            }).encode('utf-8')
            
            req = urllib.request.Request(
                "https://libretranslate.com/translate",
                data=data,
                headers={'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0'}
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                result = json.loads(response.read().decode('utf-8'))
                return result.get("translatedText")
        except:
            pass
        return None
    
    @staticmethod
    def _get_lang_code(lang: str) -> str:
        """获取语言代码"""
        lang_map = {
            "zh-CN": "zh",
            "zh-TW": "zh-TW",
            "en-US": "en",
            "en-GB": "en",
            "ja-JP": "ja",
            "ko-KR": "ko",
            "fr-FR": "fr",
            "de-DE": "de",
            "es-ES": "es",
            "pt-BR": "pt",
            "ru-RU": "ru",
            "ar-SA": "ar",
            "hi-IN": "hi",
            "it-IT": "it",
            "nl-NL": "nl",
            "pl-PL": "pl",
            "tr-TR": "tr",
            "vi-VN": "vi",
            "th-TH": "th",
            "id-ID": "id"
        }
        return lang_map.get(lang, lang[:2])
    
    @staticmethod
    def translate(text: str, target_lang: str, source_lang: str = "zh") -> Optional[str]:
        """在线翻译 - 自动尝试多个翻译源"""
        target_code = OnlineTranslator._get_lang_code(target_lang)
        source_code = OnlineTranslator._get_lang_code(source_lang)
        
        if target_code == source_code:
            return text
        
        # 按优先级尝试
        methods = [
            ("LibreTranslate", lambda: OnlineTranslator.translate_libre(text, target_code, source_code)),
            ("MyMemory", lambda: OnlineTranslator.translate_mymemory(text, target_code, source_code)),
        ]
        
        for name, method in methods:
            try:
                result = method()
                if result:
                    return result
            except:
                continue
        return None


class TranslationCache:
    """翻译缓存系统 - 本地持久化存储"""
    
    def __init__(self):
        # 使用程序目录下的翻译缓存
        if getattr(sys, 'frozen', False):
            base_dir = os.path.dirname(sys.executable)
        else:
            base_dir = os.path.dirname(os.path.abspath(__file__))
        
        self.cache_dir = os.path.join(base_dir, "i18n_cache")
        os.makedirs(self.cache_dir, exist_ok=True)
        self._cache: Dict[str, Dict[str, str]] = {}
        self._lock = threading.Lock()
        self._load_cache()
    
    def _get_cache_file(self, lang_code: str) -> str:
        """获取语言缓存文件路径"""
        return os.path.join(self.cache_dir, f"translations_{lang_code}.json")
    
    def _load_cache(self) -> None:
        """加载所有缓存"""
        with self._lock:
            self._cache = {}
            for filename in os.listdir(self.cache_dir):
                if filename.startswith("translations_") and filename.endswith(".json"):
                    lang_code = filename.replace("translations_", "").replace(".json", "")
                    filepath = os.path.join(self.cache_dir, filename)
                    try:
                        with open(filepath, 'r', encoding='utf-8') as f:
                            self._cache[lang_code] = json.load(f)
                    except:
                        self._cache[lang_code] = {}
    
    def save_cache(self, lang_code: str) -> bool:
        """保存指定语言的缓存"""
        with self._lock:
            if lang_code not in self._cache:
                return False
            filepath = self._get_cache_file(lang_code)
            try:
                with open(filepath, 'w', encoding='utf-8') as f:
                    json.dump(self._cache[lang_code], f, ensure_ascii=False, indent=2)
                return True
            except:
                return False
    
    def get(self, lang_code: str, key: str) -> Optional[str]:
        """从缓存获取翻译"""
        with self._lock:
            if lang_code in self._cache:
                return self._cache[lang_code].get(key)
            return None
    
    def set(self, lang_code: str, key: str, value: str) -> None:
        """设置缓存翻译"""
        with self._lock:
            if lang_code not in self._cache:
                self._cache[lang_code] = {}
            self._cache[lang_code][key] = value
            self.save_cache(lang_code)
    
    def get_stats(self) -> Dict[str, int]:
        """获取缓存统计"""
        stats = {}
        for lang_code, data in self._cache.items():
            stats[lang_code] = len(data)
        return stats
    
    def clear(self, lang_code: Optional[str] = None) -> None:
        """清除缓存"""
        with self._lock:
            if lang_code:
                if lang_code in self._cache:
                    del self._cache[lang_code]
                    filepath = self._get_cache_file(lang_code)
                    if os.path.exists(filepath):
                        os.remove(filepath)
            else:
                self._cache.clear()
                for filename in os.listdir(self.cache_dir):
                    if filename.startswith("translations_") and filename.endswith(".json"):
                        os.remove(os.path.join(self.cache_dir, filename))


class EnhancedTranslator:
    """增强版翻译管理器 - 支持在线翻译 + 本地缓存"""
    
    def __init__(self):
        self.cache = TranslationCache()
        self._enable_online = False
        self._stats = {"cached_hits": 0, "online_calls": 0, "failed_calls": 0}
        self._stats_lock = threading.Lock()
    
    def set_online_enabled(self, enabled: bool) -> None:
        self._enable_online = enabled
    
    def translate(self, text: str, target_lang: str, source_lang: str = "zh") -> str:
        """翻译文本 - 先查缓存，再走在线翻译"""
        if target_lang == "zh-CN":
            return text
        
        # 1. 检查缓存
        cached = self.cache.get(target_lang, text)
        if cached is not None:
            with self._stats_lock:
                self._stats["cached_hits"] += 1
            return cached
        
        # 2. 在线翻译
        if self._enable_online:
            try:
                with self._stats_lock:
                    self._stats["online_calls"] += 1
                result = OnlineTranslator.translate(text, target_lang, source_lang)
                if result:
                    self.cache.set(target_lang, text, result)
                    return result
            except:
                with self._stats_lock:
                    self._stats["failed_calls"] += 1
        
        return text
    
    def translate_batch(self, texts: List[str], target_lang: str, source_lang: str = "zh") -> List[str]:
        """批量翻译"""
        if not texts or target_lang == "zh-CN":
            return texts.copy()
        
        results = []
        for text in texts:
            results.append(self.translate(text, target_lang, source_lang))
        return results
    
    def preload_translations(self, lang_code: str, texts: List[str]) -> None:
        """预加载翻译"""
        if lang_code == "zh-CN":
            return
        to_translate = [t for t in texts if self.cache.get(lang_code, t) is None]
        if to_translate:
            self.translate_batch(to_translate, lang_code)
    
    def export_cache(self, lang_code: str, filepath: str) -> bool:
        """导出翻译缓存"""
        cache_file = self.cache._get_cache_file(lang_code)
        if not os.path.exists(cache_file):
            return False
        try:
            import shutil
            shutil.copy2(cache_file, filepath)
            return True
        except:
            return False
    
    def import_cache(self, filepath: str) -> bool:
        """导入翻译缓存"""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                data = json.load(f)
            basename = os.path.basename(filepath)
            if basename.startswith("translations_") and basename.endswith(".json"):
                lang_code = basename.replace("translations_", "").replace(".json", "")
                for key, value in data.items():
                    self.cache.set(lang_code, key, value)
                return True
            return False
        except:
            return False
    
    def clear_cache(self, lang_code: Optional[str] = None) -> None:
        self.cache.clear(lang_code)
    
    def show_stats(self) -> None:
        """显示翻译统计"""
        stats = self._stats
        cache_stats = self.cache.get_stats()
        safe_print("\n" + "=" * 50)
        safe_print("        📊 翻译统计")
        safe_print("=" * 50)
        safe_print(f"缓存命中: {stats['cached_hits']}")
        safe_print(f"在线翻译: {stats['online_calls']}")
        safe_print(f"翻译失败: {stats['failed_calls']}")
        safe_print(f"在线翻译: {'✅ 已启用' if self._enable_online else '❌ 已禁用'}")
        safe_print("-" * 50)
        safe_print("📁 缓存统计:")
        for lang_code, count in cache_stats.items():
            safe_print(f"  {lang_code}: {count} 条")
        safe_print("=" * 50)


# 创建全局翻译器实例
_translator = EnhancedTranslator()

def translate_with_cache(text: str, target_lang: Optional[str] = None) -> str:
    """带缓存的翻译函数"""
    if target_lang is None:
        target_lang = get_current_language()
    return _translator.translate(text, target_lang)

