# ==================== Emoji 兼容处理 ====================
import platform

_emoji_config_file = os.path.join(_BASE_DIR, 'emoji_config.json')
_emoji_mode = None
_emoji_lock = threading.Lock()

def _get_emoji_mode():
    global _emoji_mode
    if _emoji_mode is not None:
        return _emoji_mode
    
    try:
        if os.path.exists(_emoji_config_file):
            with open(_emoji_config_file, 'r', encoding='utf-8') as f:
                config = json.load(f)
                mode = config.get('emoji_mode', 'A').upper()
                if mode in ['A', 'T', 'F']:
                    _emoji_mode = mode
                    return _emoji_mode
    except:
        pass
    
    _emoji_mode = 'A'
    return _emoji_mode

def _should_filter_emoji():
    mode = _get_emoji_mode()
    if mode == 'T':
        return False
    if mode == 'F':
        return True
    # 自动模式：检测系统
    sys_name = platform.system()
    if sys_name == 'Windows':
        ver = platform.version()
        if ver.startswith('6.1') or ver.startswith('6.0'):
            return True
        if ver.startswith('10.0'):
            try:
                build = int(ver.split('.')[2]) if len(ver.split('.')) > 2 else 0
                return build < 15000
            except:
                return False
    return False

def _filter_emoji(text):
    if not _should_filter_emoji():
        return text
    replacements = {
        "✅": "[OK]", "❌": "[FAIL]", "⚠️": "[WARN]",
        "🔧": "[FIX]", "🔄": "[RELOAD]", "📦": "[PKG]",
        "💡": "[TIP]", "🤖": "[AI]", "👥": "[USERS]",
        "🗑️": "[DEL]", "📝": "[EDIT]", "⚡": "[POWER]",
        "🖥️": "[PC]", "🌐": "[WEB]", "📁": "[DIR]",
        "📄": "[FILE]", "🔒": "[LOCK]", "🎉": "[DONE]",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return text

def safe_print(msg: str = "", end: str = "\n", flush: bool = False) -> None:
    """线程安全的打印函数 - 永不报错"""
    try:
        # 1. Emoji 过滤
        try:
            msg = _filter_emoji(msg)
        except:
            pass
        
        # 2. 国际化翻译
        try:
            if msg and get_current_language() != "zh-CN":
                translated = translate(msg)
                if translated != msg:
                    msg = translated
        except:
            pass
        
        # 3. 打印
        try:
            with print_lock:
                print(msg, end=end, flush=flush)
        except:
            # 4. 终极兜底
            try:
                sys.stdout.write(str(msg) + end)
                sys.stdout.flush()
            except:
                pass
    except:
        pass
# ==================== Emoji 兼容处理结束 ====================

