# ==================== 沙盒执行环境 ====================

class SandboxEnvironment:
    """
    沙盒执行环境 - 限制脚本权限
    防止脚本对系统造成破坏
    """
    
    def __init__(self):
        self.allowed_modules = {
            'os': self._safe_os,
            'sys': self._safe_sys,
            'json': json,
            'datetime': datetime,
            'time': time,
            'math': math,
            'random': random,
            're': re,
            'string': string,
            'collections': collections,
            'itertools': itertools,
            'functools': functools,
        }
    
    def _safe_os(self):
        """安全的 os 模块代理"""
        class SafeOS:
            def __init__(self):
                self.path = os.path
                self.name = os.name
                self.getcwd = os.getcwd
                self.listdir = os.listdir
                self.environ = os.environ.copy()
                self.sep = os.sep
                self.linesep = os.linesep
                # 只读操作
                self.path.exists = os.path.exists
                self.path.isfile = os.path.isfile
                self.path.isdir = os.path.isdir
                self.path.getsize = os.path.getsize
                self.path.getmtime = os.path.getmtime
                self.path.getctime = os.path.getctime
                self.path.dirname = os.path.dirname
                self.path.basename = os.path.basename
                self.path.join = os.path.join
                self.path.abspath = os.path.abspath
                self.path.split = os.path.split
                self.path.splitext = os.path.splitext
                self.path.normpath = os.path.normpath
                self.path.realpath = os.path.realpath
                # 阻止写入操作
                self.remove = self._blocked
                self.unlink = self._blocked
                self.rmdir = self._blocked
                self.removedirs = self._blocked
                self.rename = self._blocked
                self.mkdir = self._blocked
                self.makedirs = self._blocked
                self.system = self._blocked
                self.popen = self._blocked
                self.execv = self._blocked
                self.execl = self._blocked
                self.kill = self._blocked
                self.chmod = self._blocked
                self.chown = self._blocked
                self.utime = self._blocked
                self.symlink = self._blocked
                self.link = self._blocked
                self.mknod = self._blocked
            
            def _blocked(self, *args, **kwargs):
                raise PermissionError("沙盒模式：该操作被禁止")
        
        return SafeOS()
    
    def _safe_sys(self):
        """安全的 sys 模块代理"""
        class SafeSys:
            def __init__(self):
                self.version = sys.version
                self.platform = sys.platform
                self.executable = sys.executable
                self.argv = sys.argv
                self.path = sys.path
                self.modules = sys.modules
                self.ps1 = sys.ps1
                self.ps2 = sys.ps2
                self.builtin_module_names = sys.builtin_module_names
                # 阻止危险操作
                self.exit = self._blocked
                self.settrace = self._blocked
                self.setprofile = self._blocked
                self.setrecursionlimit = self._blocked
                self.setswitchinterval = self._blocked
            
            def _blocked(self, *args, **kwargs):
                raise PermissionError("沙盒模式：该操作被禁止")
        
        return SafeSys()
    
    def _safe_builtins(self):
        """安全的 builtins"""
        class SafeBuiltins:
            def __getattr__(self, name):
                safe_list = [
                    'print', 'len', 'str', 'int', 'float', 'bool',
                    'list', 'dict', 'tuple', 'set', 'range', 'enumerate',
                    'zip', 'map', 'filter', 'sum', 'min', 'max', 'abs',
                    'sorted', 'reversed', 'isinstance', 'issubclass',
                    'type', 'hasattr', 'getattr', 'setattr', 'dir',
                    'chr', 'ord', 'hex', 'oct', 'bin', 'format',
                    'round', 'pow', 'divmod', 'complex', 'bytes',
                    'bytearray', 'memoryview', 'slice', 'property',
                    'staticmethod', 'classmethod', 'super', 'object',
                    'Exception', 'ValueError', 'TypeError', 'IndexError',
                    'KeyError', 'AttributeError', 'PermissionError'
                ]
                if name in safe_list:
                    return getattr(__builtins__, name)
                if name in ['open', 'file', 'input']:
                    raise PermissionError("沙盒模式：文件操作被禁止")
                if name in ['exec', 'eval', 'compile', '__import__']:
                    raise PermissionError("沙盒模式：动态代码执行被禁止")
                raise AttributeError(f"沙盒模式：'{name}' 不被允许")
        
        return SafeBuiltins()
    
    def _safe_data_management(self):
        """只读的数据管理"""
        class SafeDataManagement:
            @staticmethod
            def load_user_data():
                return DataManagement.load_user_data()
            
            @staticmethod
            def load_occupation_list():
                return DataManagement.load_occupation_list()
            
            @staticmethod
            def get_backup_list():
                return DataManagement.get_backup_list()
            
            @staticmethod
            def load_firewall_config():
                return DataManagement.load_firewall_config()
            
            @staticmethod
            def load_network_rules():
                return DataManagement.load_network_rules()
            
            @staticmethod
            def load_version():
                return DataManagement.load_version()
            
            @staticmethod
            def load_secret_question():
                return DataManagement.load_secret_question()
            
            @staticmethod
            def load_temp_keys():
                return DataManagement.load_temp_keys()
            
            @staticmethod
            def save_user_data(*args, **kwargs):
                raise PermissionError("沙盒模式：保存数据被禁止")
            
            @staticmethod
            def create_backup(*args, **kwargs):
                raise PermissionError("沙盒模式：创建备份被禁止")
            
            @staticmethod
            def save_secure_passwords(*args, **kwargs):
                raise PermissionError("沙盒模式：保存密码被禁止")
            
            @staticmethod
            def save_version(*args, **kwargs):
                raise PermissionError("沙盒模式：修改版本被禁止")
            
            @staticmethod
            def save_network_rules(*args, **kwargs):
                raise PermissionError("沙盒模式：修改网络规则被禁止")
        
        return SafeDataManagement
    
    def create_sandbox_globals(self):
        """创建沙盒环境"""
        sandbox_globals = {
            '__builtins__': self._safe_builtins(),
            'safe_print': safe_print,
            'os': self._safe_os(),
            'sys': self._safe_sys(),
            'json': json,
            'datetime': datetime,
            'time': time,
            'math': math,
            'random': random,
            're': re,
            'string': string,
            'collections': collections,
            'itertools': itertools,
            'functools': functools,
            'DataManagement': self._safe_data_management(),
            'SystemLog': SystemLog,
            'SUPPORTED_LANGUAGES': SUPPORTED_LANGUAGES,
        }
        return sandbox_globals
    
    def run_in_sandbox(self, func, *args, **kwargs):
        """在沙盒中运行函数"""
        sandbox_globals = self.create_sandbox_globals()
        
        try:
            # 保存原 globals
            original_globals = func.__globals__.copy()
            
            # 更新为沙盒环境
            func.__globals__.update(sandbox_globals)
            
            # 执行函数
            result = func(*args, **kwargs)
            
            # 恢复原 globals
            func.__globals__.clear()
            func.__globals__.update(original_globals)
            
            return result
        except PermissionError as e:
            safe_print(f"🔒 沙盒阻止: {e}")
            return None
        except Exception as e:
            safe_print(f"❌ 沙盒执行错误: {e}")
            return None


# ==================== 内置脚本注册表 ====================

BUILTIN_SCRIPTS = {}
BUILTIN_SCRIPTS_FILE = os.path.join(_BASE_DIR, "builtin_scripts.json")

class BuiltinScriptManager:
    """管理已集成的内置脚本"""
    
    @staticmethod
    def load() -> dict:
        """加载已集成的脚本列表"""
        if os.path.exists(BUILTIN_SCRIPTS_FILE):
            try:
                with open(BUILTIN_SCRIPTS_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except:
                return {}
        return {}
    
    @staticmethod
    def save(scripts: dict):
        """保存脚本列表"""
        try:
            with open(BUILTIN_SCRIPTS_FILE, 'w', encoding='utf-8') as f:
                json.dump(scripts, f, ensure_ascii=False, indent=2)
            return True
        except:
            return False
    
    @staticmethod
    def add(script_id: str, name: str, code: str, description: str = ""):
        """添加一个内置脚本"""
        scripts = BuiltinScriptManager.load()
        scripts[script_id] = {
            "name": name,
            "description": description,
            "code": code,
            "integrated_at": datetime.datetime.now().isoformat()
        }
        return BuiltinScriptManager.save(scripts)
    
    @staticmethod
    def remove(script_id: str):
        """删除一个内置脚本"""
        scripts = BuiltinScriptManager.load()
        if script_id in scripts:
            del scripts[script_id]
            return BuiltinScriptManager.save(scripts)
        return False
    
    @staticmethod
    def remove_all():
        """删除所有内置脚本"""
        return BuiltinScriptManager.save({})
    
    @staticmethod
    def list_all() -> list:
        """列出所有已集成的脚本"""
        scripts = BuiltinScriptManager.load()
        return [{"id": k, **v} for k, v in scripts.items()]
    
    @staticmethod
    def exists(script_id: str) -> bool:
        """检查脚本是否已集成"""
        scripts = BuiltinScriptManager.load()
        return script_id in scripts
# ==================== 安全引导系统 ====================

ERROR_LOG_FILE = os.path.join(_BASE_DIR, "error_log.json")

class SafeBootManager:
    """安全引导管理器 - 捕获异常，禁用问题功能"""
    
    _disabled_functions = {}
    _error_log = []
    
    # ========== 紧急打印（不依赖任何自定义函数） ==========
    
    @staticmethod
    def _emergency_print(msg: str):
        """紧急打印 - 只用于安全引导，不依赖任何自定义函数"""
        try:
            sys.stdout.write(str(msg) + "\n")
            sys.stdout.flush()
        except:
            try:
                print(str(msg))
            except:
                pass
    
    @staticmethod
    def _emergency_print_error(msg: str):
        """紧急打印错误 - 输出到 stderr"""
        try:
            sys.stderr.write(str(msg) + "\n")
            sys.stderr.flush()
        except:
            try:
                print(f"ERROR: {msg}")
            except:
                pass
    
    # ========== 键盘检测（跨平台） ==========
    
    @staticmethod
    def check_for_safe_mode() -> bool:
        """检测是否进入修复模式 - 完全跨平台"""
        try:
            import platform
            system = platform.system()
            if system == "Windows":
                return SafeBootManager._check_safe_mode_windows()
            else:
                return SafeBootManager._check_safe_mode_unix()
        except Exception:
            return False
    
    @staticmethod
    def _check_safe_mode_unix() -> bool:
        """Unix/Linux/macOS 系统检测 S 键"""
        try:
            import select
            import termios
            import tty
            import fcntl
            
            if not sys.stdin.isatty():
                return False
            
            fd = sys.stdin.fileno()
            old_settings = termios.tcgetattr(fd)
            old_fl = None
            
            try:
                tty.setraw(fd)
                old_fl = fcntl.fcntl(fd, fcntl.F_GETFL)
                fcntl.fcntl(fd, fcntl.F_SETFL, old_fl | os.O_NONBLOCK)
                
                start_time = time.time()
                s_count = 0
                
                while time.time() - start_time < 3:
                    try:
                        rlist, _, _ = select.select([sys.stdin], [], [], 0.05)
                        if rlist:
                            char = sys.stdin.read(1)
                            if char and char.lower() == 's':
                                s_count += 1
                                if s_count >= 3:
                                    return True
                    except:
                        pass
                    time.sleep(0.05)
                
                return False
                
            finally:
                try:
                    termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
                except:
                    pass
                try:
                    if old_fl is not None:
                        fcntl.fcntl(fd, fcntl.F_SETFL, old_fl)
                except:
                    pass
                
        except (ImportError, AttributeError, Exception):
            return False
    
    @staticmethod
    def _check_safe_mode_windows() -> bool:
        """Windows 系统检测 S 键"""
        try:
            import msvcrt
            start_time = time.time()
            s_count = 0
            
            while time.time() - start_time < 3:
                if msvcrt.kbhit():
                    try:
                        char = msvcrt.getch()
                        if isinstance(char, bytes):
                            char = char.decode('ascii', errors='ignore')
                        else:
                            char = str(char)
                        if char.lower() == 's':
                            s_count += 1
                            if s_count >= 3:
                                return True
                    except:
                        pass
                time.sleep(0.05)
            return False
        except ImportError:
            return False
    
    # ========== 错误日志管理 ==========
    
    @staticmethod
    def load_error_log() -> dict:
        """加载错误日志"""
        if os.path.exists(ERROR_LOG_FILE):
            try:
                with open(ERROR_LOG_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except:
                return {}
        return {}
    
    @staticmethod
    def save_error_log(log: dict):
        """保存错误日志"""
        try:
            with open(ERROR_LOG_FILE, 'w', encoding='utf-8') as f:
                json.dump(log, f, ensure_ascii=False, indent=2)
            return True
        except:
            return False
    
    # ========== 功能禁用/启用 ==========
    
    @staticmethod
    def disable_function(func_name: str, error: str, func_type: str = "function"):
        """禁用某个功能"""
        try:
            log = SafeBootManager.load_error_log()
            
            if func_name not in log:
                log[func_name] = {
                    "name": func_name,
                    "type": func_type,
                    "disabled": True,
                    "error": str(error),
                    "disabled_at": datetime.datetime.now().isoformat(),
                    "call_count": 0
                }
            else:
                log[func_name]["disabled"] = True
                log[func_name]["error"] = str(error)
                log[func_name]["disabled_at"] = datetime.datetime.now().isoformat()
            
            SafeBootManager.save_error_log(log)
            SafeBootManager._disabled_functions[func_name] = log[func_name]
            
            SafeBootManager._emergency_print(f"⚠️ 安全引导: 已禁用功能 '{func_name}'")
            SafeBootManager._emergency_print(f"   原因: {str(error)[:100]}")
            SafeBootManager._emergency_print(f"   💡 请开发者修复后重新启用")
        except Exception as e:
            SafeBootManager._emergency_print_error(f"安全引导内部错误: {e}")
    
    @staticmethod
    def enable_function(func_name: str):
        """重新启用某个功能"""
        try:
            log = SafeBootManager.load_error_log()
            
            if func_name in log:
                log[func_name]["disabled"] = False
                log[func_name]["error"] = ""
                log[func_name]["enabled_at"] = datetime.datetime.now().isoformat()
                SafeBootManager.save_error_log(log)
                
                if func_name in SafeBootManager._disabled_functions:
                    del SafeBootManager._disabled_functions[func_name]
                
                SafeBootManager._emergency_print(f"✅ 功能 '{func_name}' 已重新启用")
                return True
        except Exception as e:
            SafeBootManager._emergency_print_error(f"启用功能失败: {e}")
        return False
    
    @staticmethod
    def is_disabled(func_name: str) -> bool:
        """检查某个功能是否被禁用"""
        try:
            log = SafeBootManager.load_error_log()
            if func_name in log:
                return log[func_name].get("disabled", False)
        except:
            pass
        return False
    
    @staticmethod
    def get_disabled_list() -> list:
        """获取所有被禁用的功能列表"""
        try:
            log = SafeBootManager.load_error_log()
            return [{"name": k, **v} for k, v in log.items() if v.get("disabled", False)]
        except:
            return []
    
    @staticmethod
    def get_all_errors() -> list:
        """获取所有错误记录"""
        try:
            log = SafeBootManager.load_error_log()
            return [{"name": k, **v} for k, v in log.items()]
        except:
            return []
    
    @staticmethod
    def clear_all_errors():
        """清除所有错误记录"""
        try:
            SafeBootManager.save_error_log({})
            SafeBootManager._disabled_functions.clear()
            SafeBootManager._emergency_print("✅ 已清除所有错误记录")
        except Exception as e:
            SafeBootManager._emergency_print_error(f"清除错误记录失败: {e}")
    
    @staticmethod
    def record_call(func_name: str):
        """记录功能被调用的次数"""
        try:
            log = SafeBootManager.load_error_log()
            if func_name in log:
                log[func_name]["call_count"] = log[func_name].get("call_count", 0) + 1
                SafeBootManager.save_error_log(log)
        except:
            pass
    
    # ========== 安全调用 ==========
    
    @staticmethod
    def safe_call(func, func_name: str, *args, **kwargs):
        """安全调用函数"""
        try:
            if SafeBootManager.is_disabled(func_name):
                SafeBootManager.record_call(func_name)
                return None, f"⚠️ 功能 '{func_name}' 已被禁用，请开发者修复"
            
            try:
                result = func(*args, **kwargs)
                return result, None
            except Exception as e:
                import traceback
                error_detail = f"{str(e)}\n{traceback.format_exc()}"
                SafeBootManager.disable_function(func_name, error_detail)
                return None, f"❌ 功能 '{func_name}' 执行失败，已被安全引导禁用"
        except Exception as e:
            SafeBootManager._emergency_print_error(f"安全调用失败: {e}")
            return None, f"安全引导内部错误: {e}"
    
    @staticmethod
    def safe_call_with_retry(func, func_name: str, max_retries: int = 3, *args, **kwargs):
        """安全调用函数 - 支持重试"""
        try:
            if SafeBootManager.is_disabled(func_name):
                SafeBootManager.record_call(func_name)
                return None, f"⚠️ 功能 '{func_name}' 已被禁用，请开发者修复"
            
            last_error = None
            for attempt in range(max_retries):
                try:
                    result = func(*args, **kwargs)
                    if SafeBootManager.is_disabled(func_name):
                        SafeBootManager.enable_function(func_name)
                    return result, None
                except Exception as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        time.sleep(0.5)
            
            import traceback
            error_detail = f"{str(last_error)}\n{traceback.format_exc()}"
            SafeBootManager.disable_function(func_name, error_detail)
            return None, f"❌ 功能 '{func_name}' 重试 {max_retries} 次后失败，已被安全引导禁用"
        except Exception as e:
            SafeBootManager._emergency_print_error(f"安全调用重试失败: {e}")
            return None, f"安全引导内部错误: {e}"
    
    # ========== 修复模式 ==========
    
    @staticmethod
    def enter_repair_mode():
        """进入修复模式"""
        SafeBootManager._emergency_print("\n" + "=" * 60)
        SafeBootManager._emergency_print("           🔧 安全引导修复模式")
        SafeBootManager._emergency_print("=" * 60)
        SafeBootManager._emergency_print("检测到 S 键被按下，进入修复模式...")
        SafeBootManager._emergency_print("=" * 60)
        
        while True:
            SafeBootManager._emergency_print("\n请选择操作:")
            SafeBootManager._emergency_print("1. 🔧 自动修复所有被禁用的功能")
            SafeBootManager._emergency_print("2. 💻 进入安全命令行 (仅基础命令)")
            SafeBootManager._emergency_print("3. 📋 查看/编辑错误日志")
            SafeBootManager._emergency_print("4. 🚀 继续正常启动系统")
            SafeBootManager._emergency_print("5. 🔄 重置系统配置 (恢复默认)")
            SafeBootManager._emergency_print("6. 🗑️  清除所有错误记录")
            SafeBootManager._emergency_print("7. ⏹️  退出系统")
            SafeBootManager._emergency_print("=" * 60)
            
            choice = SafeBootManager._get_repair_input("请输入选择 (1-7): ")
            
            if choice == "1":
                SafeBootManager.auto_repair_all()
            elif choice == "2":
                SafeBootManager.safe_command_line()
            elif choice == "3":
                SafeBootManager.view_error_log()
            elif choice == "4":
                SafeBootManager._emergency_print("\n🔄 继续启动系统...")
                break
            elif choice == "5":
                SafeBootManager.reset_system_config()
            elif choice == "6":
                SafeBootManager.clear_all_errors()
            elif choice == "7":
                SafeBootManager._emergency_print("\n👋 系统退出")
                sys.exit(0)
            else:
                SafeBootManager._emergency_print("❌ 无效选择")
    
    @staticmethod
    def _get_repair_input(prompt: str) -> str:
        """获取修复模式输入"""
        try:
            return input(prompt).strip()
        except:
            try:
                return sys.stdin.readline().strip()
            except:
                return ""
    
    @staticmethod
    def auto_repair_all():
        """自动修复所有被禁用的功能"""
        SafeBootManager._emergency_print("\n🔧 正在自动修复所有被禁用的功能...")
        
        disabled = SafeBootManager.get_disabled_list()
        if not disabled:
            SafeBootManager._emergency_print("✅ 没有被禁用的功能")
            return
        
        repaired = 0
        for item in disabled:
            func_name = item['name']
            SafeBootManager._emergency_print(f"   正在修复: {func_name}...")
            if SafeBootManager.enable_function(func_name):
                repaired += 1
                SafeBootManager._emergency_print(f"   ✅ {func_name} 已修复")
            else:
                SafeBootManager._emergency_print(f"   ❌ {func_name} 修复失败")
        
        SafeBootManager._emergency_print(f"\n✅ 修复完成: {repaired}/{len(disabled)} 个功能已恢复")
    
    @staticmethod
    def safe_command_line():
        """安全命令行 - 只提供最基础的安全命令"""
        SafeBootManager._emergency_print("\n💻 进入安全命令行模式")
        SafeBootManager._emergency_print("可用命令: help, list, enable <功能名>, disable <功能名>, clear, exit")
        SafeBootManager._emergency_print("-" * 40)
        
        while True:
            try:
                cmd = SafeBootManager._get_repair_input("修复模式> ").strip()
                if not cmd:
                    continue
                
                parts = cmd.split()
                command = parts[0].lower()
                
                if command in ['exit', 'quit', 'q']:
                    SafeBootManager._emergency_print("退出安全命令行")
                    break
                
                elif command in ['help', '?']:
                    SafeBootManager._emergency_print("\n可用命令:")
                    SafeBootManager._emergency_print("  help / ?        - 显示帮助")
                    SafeBootManager._emergency_print("  list / ls       - 列出所有被禁用的功能")
                    SafeBootManager._emergency_print("  list all        - 列出所有功能状态")
                    SafeBootManager._emergency_print("  enable <名称>   - 重新启用功能")
                    SafeBootManager._emergency_print("  disable <名称>  - 禁用功能")
                    SafeBootManager._emergency_print("  clear           - 清除所有错误记录")
                    SafeBootManager._emergency_print("  exit / quit / q - 退出安全命令行")
                    SafeBootManager._emergency_print("  view            - 查看错误日志")
                
                elif command in ['list', 'ls']:
                    if len(parts) > 1 and parts[1] == 'all':
                        errors = SafeBootManager.get_all_errors()
                        if errors:
                            SafeBootManager._emergency_print("\n所有功能状态:")
                            for e in errors:
                                status = "🚫 禁用" if e.get("disabled") else "✅ 正常"
                                SafeBootManager._emergency_print(f"  {e['name']}: {status}")
                        else:
                            SafeBootManager._emergency_print("没有错误记录")
                    else:
                        disabled = SafeBootManager.get_disabled_list()
                        if disabled:
                            SafeBootManager._emergency_print("\n被禁用的功能:")
                            for i, d in enumerate(disabled, 1):
                                SafeBootManager._emergency_print(f"  {i}. {d['name']}")
                                SafeBootManager._emergency_print(f"     错误: {d.get('error', '')[:60]}...")
                        else:
                            SafeBootManager._emergency_print("没有被禁用的功能")
                
                elif command == 'enable':
                    if len(parts) < 2:
                        SafeBootManager._emergency_print("用法: enable <功能名>")
                        continue
                    func_name = parts[1]
                    if SafeBootManager.enable_function(func_name):
                        SafeBootManager._emergency_print(f"✅ {func_name} 已重新启用")
                    else:
                        SafeBootManager._emergency_print(f"❌ 启用失败: {func_name} 不存在或已启用")
                
                elif command == 'disable':
                    if len(parts) < 2:
                        SafeBootManager._emergency_print("用法: disable <功能名>")
                        continue
                    func_name = parts[1]
                    SafeBootManager.disable_function(func_name, "手动禁用")
                    SafeBootManager._emergency_print(f"✅ {func_name} 已禁用")
                
                elif command == 'clear':
                    confirm = SafeBootManager._get_repair_input("确定清除所有错误记录？(Y/N): ").upper()
                    if confirm == 'Y':
                        SafeBootManager.clear_all_errors()
                    else:
                        SafeBootManager._emergency_print("操作已取消")
                
                elif command == 'view':
                    SafeBootManager.view_error_log()
                
                else:
                    SafeBootManager._emergency_print(f"未知命令: {command}")
                    SafeBootManager._emergency_print("输入 'help' 查看可用命令")
                    
            except KeyboardInterrupt:
                SafeBootManager._emergency_print("\n退出安全命令行")
                break
            except Exception as e:
                SafeBootManager._emergency_print(f"错误: {e}")
    
    @staticmethod
    def view_error_log():
        """查看错误日志"""
        SafeBootManager._emergency_print("\n📋 === 错误日志 ===")
        
        errors = SafeBootManager.get_all_errors()
        if not errors:
            SafeBootManager._emergency_print("没有错误记录")
            return
        
        for i, e in enumerate(errors, 1):
            status = "🚫 已禁用" if e.get("disabled") else "✅ 已启用"
            SafeBootManager._emergency_print(f"\n{i}. {e['name']} - {status}")
            SafeBootManager._emergency_print(f"   类型: {e.get('type', '未知')}")
            SafeBootManager._emergency_print(f"   调用次数: {e.get('call_count', 0)}")
            if e.get("disabled_at"):
                SafeBootManager._emergency_print(f"   禁用时间: {e['disabled_at']}")
            if e.get("error"):
                SafeBootManager._emergency_print(f"   错误信息: {e['error'][:150]}...")
        
        SafeBootManager._emergency_print(f"\n共 {len(errors)} 条记录")
    
    @staticmethod
    def reset_system_config():
        """重置系统配置"""
        SafeBootManager._emergency_print("\n🔄 重置系统配置...")
        
        confirm = SafeBootManager._get_repair_input("确定重置所有系统配置为默认值？(Y/N): ").upper()
        if confirm != 'Y':
            SafeBootManager._emergency_print("操作已取消")
            return
        
        try:
            SafeBootManager.clear_all_errors()
            
            config = ConfigManager()
            config._create_default()
            
            SafeBootManager._disabled_functions.clear()
            
            SafeBootManager._emergency_print("✅ 系统配置已重置为默认值")
            SafeBootManager._emergency_print("💡 建议重启系统以应用所有更改")
            
            reboot = SafeBootManager._get_repair_input("是否立即重启？(Y/N): ").upper()
            if reboot == 'Y':
                SafeBootManager._emergency_print("🔄 正在重启...")
                import subprocess
                subprocess.Popen([sys.executable] + sys.argv)
                sys.exit(0)
                
        except Exception as e:
            SafeBootManager._emergency_print(f"❌ 重置失败: {e}")
# ==================== 脚本引擎 ====================
class ScriptEngine:
    """PWOS 脚本引擎（你原来的 #main 风格 + 增强内置函数）"""
    
    def __init__(self):
        self.base_dir = self._get_base_dir()
        self.scripts_dir = os.path.join(self.base_dir, "scripts")
        self.menu_items = []      # (编号, 代码行列表 或 函数引用)
        self.functions = {}       # 函数名 -> 代码行列表
        self.vars = {}            # 运行时变量
        self.script_metadata = {} # 脚本元数据
        self.builtins = {}        # 内置函数
        self.std_lib = None
        self.custom_libs = {}
        self._ensure_scripts_dir()
        self._register_builtins()
        self._init_stdlib()
        self._setup_import_handler()
        self._load_builtin_scripts()  # 先加载已集成的脚本
        self._load_all_scripts()      # 再加载外部脚本文件
        global _script_cache
        _script_cache = None
    
    def _handle_import(self, import_line, env):
        """处理 #import 语句"""
        parts = import_line.split()
        if len(parts) < 2:
            return
        
        lib_name = parts[1]
        
        # 1. 如果导入的是 std（全能标准库）
        if lib_name == "std":
            if self.std_lib:
                env['std'] = self.std_lib
                safe_print(f"✅ 已导入全能标准库 std")
            else:
                safe_print(f"⚠️ 标准库不可用")
            return
        
        # 2. 检查是否已缓存
        if lib_name in self.custom_libs:
            env[lib_name] = self.custom_libs[lib_name]
            safe_print(f"✅ 已导入自定义库 {lib_name}（缓存）")
            return
        
        # 3. 尝试加载用户自定义库
        lib_path = self._find_custom_lib(lib_name)
        if lib_path:
            try:
                import importlib.util
                spec = importlib.util.spec_from_file_location(lib_name, lib_path)
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                
                if hasattr(module, lib_name):
                    lib_instance = getattr(module, lib_name)
                elif hasattr(module, "lib"):
                    lib_instance = module.lib
                else:
                    lib_instance = module
                
                self.custom_libs[lib_name] = lib_instance
                env[lib_name] = lib_instance
                safe_print(f"✅ 已导入自定义库 {lib_name}")
            except Exception as e:
                safe_print(f"❌ 导入库 {lib_name} 失败: {e}")
        else:
            safe_print(f"❌ 未找到库: {lib_name}")

    def _find_custom_lib(self, lib_name):
        """查找用户自定义库文件"""
        search_paths = [
            os.path.join(self.scripts_dir, "libs", f"{lib_name}.py"),
            os.path.join(self.scripts_dir, f"{lib_name}.py"),
            os.path.join(self.base_dir, f"{lib_name}.py"),
        ]
        
        for path in search_paths:
            if os.path.exists(path):
                return path
        return None

    def _get_base_dir(self):
        if getattr(sys, 'frozen', False):
            return os.path.dirname(sys.executable)
        return os.path.dirname(os.path.abspath(__file__))

    def _ensure_scripts_dir(self):
        if not os.path.exists(self.scripts_dir):
            os.makedirs(self.scripts_dir)

    def _load_builtin_scripts(self):
        """从注册表加载已集成的脚本"""
        scripts = BuiltinScriptManager.load()
        for script_id, script_data in scripts.items():
            bid = f"builtin_{script_id}"
            code_lines = script_data.get("code", "").split('\n')
            
            # 添加到菜单
            self.menu_items.append((bid, code_lines))
            
            # 保存元数据
            self.script_metadata[bid] = {
                "name": script_data.get("name", f"脚本 {script_id}"),
                "description": script_data.get("description", ""),
                "builtin": True,
                "is_function": False,
                "id": script_id,
                "integrated": True
            }

    def _load_all_scripts(self):
        """加载所有外部脚本文件"""
        for fname in os.listdir(self.scripts_dir):
            if not fname.endswith(".pwos"):
                continue
            self._parse_script(os.path.join(self.scripts_dir, fname))

    def _parse_script(self, path):
        """解析脚本文件（支持头部配置）"""
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        # 解析头部配置
        integrate = False
        allow_sandbox = False
        script_name = ""
        description = ""
        
        for line in lines[:20]:
            line = line.strip()
            if line.startswith('# in:'):
                try:
                    val = line.split('# in:')[1].strip()
                    integrate = val in ['1', 'true', 'yes', '是']
                except:
                    pass
            elif line.startswith('# sa:'):
                try:
                    val = line.split('# sa:')[1].strip()
                    allow_sandbox = val in ['1', 'true', 'yes', '是']
                except:
                    pass
            elif line.startswith('# name:'):
                try:
                    script_name = line.split('# name:')[1].strip()
                except:
                    pass
            elif line.startswith('# desc:'):
                try:
                    description = line.split('# desc:')[1].strip()
                except:
                    pass

        # 解析主代码
        i = 0
        while i < len(lines):
            line = lines[i].strip()
            
            if line.startswith('#main'):
                parts = line.split()
                if len(parts) >= 2:
                    bid = parts[1].rstrip(':')
                    code = []
                    i += 1
                    while i < len(lines) and not lines[i].strip().startswith(f'#main {bid} stop'):
                        code.append(lines[i])
                        i += 1
                    
                    # 保存脚本元数据
                    self.script_metadata[bid] = {
                        "name": script_name or f"脚本 {bid}",
                        "integrate": integrate,
                        "description": description,
                        "allow_sandbox": allow_sandbox,
                        "builtin": False,
                        "is_function": False,
                        "source_file": os.path.basename(path)
                    }
                    
                    # 如果需要集成，保存到注册表
                    if integrate:
                        self._integrate_script(bid, code, script_name, description, path)
                    
                    # 无论如何都添加到菜单（已集成的也显示，但标记为已集成）
                    self.menu_items.append((bid, code))
                    
            elif line.startswith('#func'):
                parts = line.split()
                if len(parts) >= 2:
                    fname = parts[1].rstrip(':')
                    code = []
                    i += 1
                    while i < len(lines) and not lines[i].strip().startswith('#func stop'):
                        code.append(lines[i])
                        i += 1
                    self.functions[fname] = code
            i += 1

    def _integrate_script(self, bid: str, code: list, name: str, description: str, source_path: str):
        """将脚本永久集成到系统"""
        # 生成唯一ID
        script_id = hashlib.md5(f"{bid}_{source_path}".encode()).hexdigest()[:8]
        
        # 检查是否已经集成
        if BuiltinScriptManager.exists(script_id):
            safe_print(f"ℹ️ 脚本 '{name}' 已集成，跳过")
            return
        
        # 保存到注册表
        full_code = '\n'.join(code)
        success = BuiltinScriptManager.add(script_id, name, full_code, description)
        
        if success:
            safe_print(f"✅ 脚本 '{name}' 已永久集成到系统！(ID: {script_id})")
            safe_print(f"   💡 现在可以删除源文件: {os.path.basename(source_path)}")
        else:
            safe_print(f"❌ 集成脚本 '{name}' 失败")

    def _init_stdlib(self):
        """初始化全能标准库"""
        try:
            from std_lib import std
            self.std_lib = std
        except ImportError:
            self.std_lib = None

    def _setup_import_handler(self):
        """设置 #import 处理器"""
        if self.std_lib:
            self.builtins['std'] = self.std_lib

    def execute_block(self, code_lines, local_vars=None):
        """执行代码块"""
        if local_vars is None:
            local_vars = {}
        env = {**self.vars, **self.builtins, **local_vars}
        env['print'] = safe_print
        env['input'] = input

        for line in code_lines:
            line = line.strip()
            if not line or line.startswith('#'):
                if line.startswith('#import'):
                    self._handle_import(line, env)
                continue

            try:
                exec(line, env)
            except Exception as e:
                safe_print(f"脚本错误: {e}")
                return

    def run_main(self, bid, developer_mode=False, use_sandbox=False):
        """运行主脚本（支持函数和代码两种模式）"""
        for menu_bid, code_or_func in self.menu_items:
            if menu_bid == bid:
                if isinstance(code_or_func, types.FunctionType):
                    try:
                        if use_sandbox:
                            safe_print("🔒 正在沙盒中运行...")
                            sandbox = SandboxEnvironment()
                            result = sandbox.run_in_sandbox(code_or_func)
                            if result is not None:
                                return "SCRIPT_EXECUTED"
                            return "SCRIPT_ERROR"
                        else:
                            code_or_func()
                            return "SCRIPT_EXECUTED"
                    except Exception as e:
                        safe_print(f"脚本错误: {e}")
                        import traceback
                        traceback.print_exc()
                        return "SCRIPT_ERROR"
                
                # 构建所有函数的定义
                func_definitions = []
                for func_name, func_lines in self.functions.items():
                    func_definitions.append(f"def {func_name}():")
                    for line in func_lines:
                        if line.strip():
                            if line.startswith('    ') or line.startswith('\t'):
                                func_definitions.append(line.rstrip())
                            else:
                                func_definitions.append(f"    {line.rstrip()}")
                        else:
                            func_definitions.append("")
                    func_definitions.append("")
                
                script_parts = []
                if func_definitions:
                    script_parts.extend(func_definitions)
                    script_parts.append("")
                script_parts.extend(code_or_func)
                full_code = '\n'.join(script_parts)
                
                env = {
                    **self.vars, 
                    **self.builtins,
                    'SCRIPT_DIR': self.base_dir,
                    'BASE_DIR': self.base_dir,
                    'print': safe_print,
                    'input': input
                }
                
                if use_sandbox:
                    safe_print("🔒 正在沙盒中运行...")
                    sandbox = SandboxEnvironment()
                    sandbox_globals = sandbox.create_sandbox_globals()
                    env.update(sandbox_globals)
                    env['exec'] = None
                    env['eval'] = None
                    env['__import__'] = None
                    env['compile'] = None
                
                try:
                    exec(full_code, env)
                    return "SCRIPT_EXECUTED"
                except Exception as e:
                    safe_print(f"脚本错误: {e}")
                    import traceback
                    traceback.print_exc()
                    return "SCRIPT_ERROR"
        return "SCRIPT_NOT_FOUND"

    def call_func(self, name, args=None):
        """调用函数"""
        if name in self.functions:
            return self.execute_block(self.functions[name])
        else:
            safe_print(f"函数 {name} 未定义")

    def get_menu_items(self):
        """获取菜单项（兼容旧版）"""
        return [(f"脚本 {bid}", bid) for bid, _ in self.menu_items]

    def get_menu_items_detailed(self):
        """获取菜单项（返回详细字典）"""
        import types
        items = []
        for bid, code_or_func in self.menu_items:
            meta = self.script_metadata.get(bid, {})
            is_function = isinstance(code_or_func, types.FunctionType)
            items.append({
                "bid": bid,
                "name": meta.get("name", f"脚本 {bid}"),
                "integrate": meta.get("integrate", False),
                "builtin": meta.get("builtin", False),
                "integrated": meta.get("integrated", False),
                "description": meta.get("description", ""),
                "is_function": is_function,
                "allow_sandbox": meta.get("allow_sandbox", False),
                "code_or_func": code_or_func
            })
        return items

    def reload(self):
        """重新加载所有脚本"""
        self.menu_items.clear()
        self.functions.clear()
        self.script_metadata.clear()
        self.custom_libs.clear()
        self._load_builtin_scripts()
        self._load_all_scripts()
        safe_print(f"✅ 重载 {len(self.menu_items)} 个脚本，{len(self.functions)} 个函数")

    def edit_script(self, name="new.pwos"):
        """编辑脚本"""
        path = os.path.join(self.scripts_dir, name)
        if not os.path.exists(path):
            with open(path, 'w', encoding='utf-8') as f:
                f.write('#main 0:\n    print("hello")\n#main 0 stop\n')
        os.startfile(path) if sys.platform == 'win32' else subprocess.run(['open', path])

    def _register_builtins(self):
        """注册200+内置函数"""
        self.builtins = {}

        # 文件操作
        self.builtins['file_read'] = lambda p: open(p, encoding='utf-8').read()
        self.builtins['file_write'] = lambda p, c: open(p, 'w', encoding='utf-8').write(c) or True
        self.builtins['file_append'] = lambda p, c: open(p, 'a', encoding='utf-8').write(c) or True
        self.builtins['file_copy'] = shutil.copy2
        self.builtins['file_move'] = shutil.move
        self.builtins['file_delete'] = lambda p: os.remove(p) if os.path.isfile(p) else shutil.rmtree(p)
        self.builtins['file_exists'] = os.path.exists
        self.builtins['file_size'] = os.path.getsize
        self.builtins['dir_create'] = lambda p: os.makedirs(p, exist_ok=True)
        self.builtins['dir_list'] = os.listdir

        # 网络 / 加密 / 压缩
        self.builtins['http_get'] = lambda u: __import__('requests').get(u).text
        self.builtins['md5'] = lambda s: __import__('hashlib').md5(s.encode()).hexdigest()
        self.builtins['sha256'] = lambda s: __import__('hashlib').sha256(s.encode()).hexdigest()
        self.builtins['zip_create'] = lambda z, f: __import__('zipfile').ZipFile(z,'w').write(f)
        self.builtins['zip_extract'] = lambda z, t: __import__('zipfile').ZipFile(z).extractall(t)

        # 系统 / 数学 / 字符串 / 时间
        self.builtins['run_cmd'] = lambda c: __import__('subprocess').run(c, shell=True).returncode
        self.builtins['now'] = lambda: __import__('datetime').datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.builtins['sleep'] = __import__('time').sleep
        self.builtins['randint'] = __import__('random').randint
        self.builtins['len'] = len
        self.builtins['print'] = safe_print
        self.builtins['input'] = input

        # PWOS 原生命令
        self.builtins['run'] = lambda s: __import__('subprocess').run(['python', s])
        self.builtins['web'] = lambda a: safe_print(f"[web] {a}")
        self.builtins['fire'] = lambda a, i: safe_print(f"[firewall] {a} {i}")
        self.builtins['notify'] = lambda t, m: safe_print(f"[通知] {t}: {m}")

        # 常用别名
        self.builtins['abs'] = abs
        self.builtins['round'] = round
        self.builtins['str'] = str
        self.builtins['int'] = int


# 初始化脚本引擎（延迟加载）
script_engine = None

def get_script_engine():
    """获取脚本引擎实例（延迟初始化）"""
    global script_engine
    if script_engine is None:
        script_engine = ScriptEngine()
    return script_engine
# ==================== 统一配置管理器 ====================
import configparser

class ConfigManager:
    """
    统一配置管理器
    处理 config.ini 的读写
    """
    _instance = None
    _config = None
    _config_file = None
    
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._init()
        return cls._instance
    
    def _init(self):
        """初始化配置"""
        self._config = configparser.ConfigParser()
        self._config_file = os.path.join(_BASE_DIR, 'config.ini')
        self._load()
    
    def _load(self):
        """加载配置文件"""
        if os.path.exists(self._config_file):
            self._config.read(self._config_file, encoding='utf-8')
            self._migrate_if_needed()
            self._migrate_old_ai_config()  # 新增：迁移旧版AI配置
            self._migrate_old_emoji_config()  # 新增：迁移旧版Emoji配置
            self._migrate_old_i18n_config()  # 新增：迁移旧版I18N配置
        else:
            self._create_default()
            self._migrate_old_configs_from_files()  # 新增：从旧文件迁移

    def _migrate_old_ai_config(self):
        """迁移旧版AI配置文件"""
        old_ai_file = os.path.join(_BASE_DIR, 'user_system_data', 'ai_config.json')
        if os.path.exists(old_ai_file):
            try:
                with open(old_ai_file, 'r', encoding='utf-8') as f:
                    ai_data = json.load(f)
                if ai_data:
                    self.set('AI', 'providers', json.dumps(ai_data.get('providers', {})))
                    self.set('AI', 'temperature', str(ai_data.get('temperature', 0.7)))
                    self.set('AI', 'max_tokens', str(ai_data.get('max_tokens', 1000)))
                    self.save()
                    # 备份并删除旧文件
                    backup_file = old_ai_file + '.bak'
                    if not os.path.exists(backup_file):
                        shutil.copy2(old_ai_file, backup_file)
                    os.remove(old_ai_file)
                    safe_print("✅ 已迁移旧版AI配置到 config.ini")
            except:
                pass

    def _migrate_old_emoji_config(self):
        """迁移旧版Emoji配置"""
        old_emoji_file = os.path.join(_BASE_DIR, 'emoji_config.json')
        if os.path.exists(old_emoji_file):
            try:
                with open(old_emoji_file, 'r', encoding='utf-8') as f:
                    emoji_data = json.load(f)
                if emoji_data:
                    self.set('Emoji', 'mode', emoji_data.get('emoji_mode', 'A'))
                    self.save()
                    os.remove(old_emoji_file)
                    safe_print("✅ 已迁移旧版Emoji配置到 config.ini")
            except:
                pass

    def _migrate_old_i18n_config(self):
        """迁移旧版I18N配置"""
        old_i18n_file = os.path.join(_BASE_DIR, 'i18n_config.json')
        if os.path.exists(old_i18n_file):
            try:
                with open(old_i18n_file, 'r', encoding='utf-8') as f:
                    i18n_data = json.load(f)
                if i18n_data:
                    self.set('I18N', 'language', i18n_data.get('language', 'auto'))
                    self.set('I18N', 'fallback', i18n_data.get('fallback', 'zh-CN'))
                    self.save()
                    os.remove(old_i18n_file)
                    safe_print("✅ 已迁移旧版I18N配置到 config.ini")
            except:
                pass

    def _migrate_old_configs_from_files(self):
        """从旧配置文件迁移所有配置"""
        # AI配置
        old_ai_file = os.path.join(_BASE_DIR, 'user_system_data', 'ai_config.json')
        if os.path.exists(old_ai_file):
            self._migrate_old_ai_config()
        
        # Emoji配置
        old_emoji_file = os.path.join(_BASE_DIR, 'emoji_config.json')
        if os.path.exists(old_emoji_file):
            self._migrate_old_emoji_config()
        
        # I18N配置
        old_i18n_file = os.path.join(_BASE_DIR, 'i18n_config.json')
        if os.path.exists(old_i18n_file):
            self._migrate_old_i18n_config()
        
        # 如果所有迁移都成功，提示用户
        self.save()
    
    def _create_default(self):
        """创建默认配置"""
        # [System]
        if not self._config.has_section('System'):
            self._config.add_section('System')
        self._config.set('System', 'version', '5.0')
        self._config.set('System', 'developer_mode', 'false')
        
        # [Security] - 使用默认密码的哈希
        if not self._config.has_section('Security'):
            self._config.add_section('Security')
        salt, hash_val = self._hash_password('a1b2c3d4e5')
        self._config.set('Security', 'developer_password_salt', salt)
        self._config.set('Security', 'developer_password_hash', hash_val)
        
        # [Encryption]
        if not self._config.has_section('Encryption'):
            self._config.add_section('Encryption')
        self._config.set('Encryption', 'data_encryption_enabled', 'true')
        self._config.set('Encryption', 'key_file', 'user_system_data/pwos_data.key')
        
        # [I18N]
        if not self._config.has_section('I18N'):
            self._config.add_section('I18N')
        self._config.set('I18N', 'language', 'auto')
        self._config.set('I18N', 'fallback', 'zh-CN')
        
        # [Emoji]
        if not self._config.has_section('Emoji'):
            self._config.add_section('Emoji')
        self._config.set('Emoji', 'mode', 'A')
        
        # [AI]
        if not self._config.has_section('AI'):
            self._config.add_section('AI')
        self._config.set('AI', 'providers', '{}')
        self._config.set('AI', 'temperature', '0.7')
        self._config.set('AI', 'max_tokens', '1000')
        
        # [Paths]
        if not self._config.has_section('Paths'):
            self._config.add_section('Paths')
        self._config.set('Paths', 'data_dir', 'user_system_data')
        self._config.set('Paths', 'update_dir', 'update_packages')
        self._config.set('Paths', 'backup_dir', 'user_system_data/backups')
        
        self.save()
    
    def _migrate_if_needed(self):
        """从旧配置迁移数据"""
        # 检查是否需要迁移开发者密码
        if self._config.has_section('Security') and \
           self._config.has_option('Security', 'developer_password_hash'):
            return
        
        # 迁移开发者密码
        salt, hash_val = self._hash_password('a1b2c3d4e5')
        if not self._config.has_section('Security'):
            self._config.add_section('Security')
        self._config.set('Security', 'developer_password_salt', salt)
        self._config.set('Security', 'developer_password_hash', hash_val)
        self.save()
    
    def _hash_password(self, password: str) -> Tuple[str, str]:
        """哈希密码"""
        import hashlib
        salt = secrets.token_hex(16)
        hash_obj = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000
        )
        return salt, hash_obj.hex()
    
    def verify_developer_password(self, password: str) -> bool:
        """验证开发者密码"""
        if not self._config.has_section('Security'):
            return False
        
        salt = self._config.get('Security', 'developer_password_salt')
        stored_hash = self._config.get('Security', 'developer_password_hash')
        
        hash_obj = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000
        )
        return hash_obj.hex() == stored_hash
    
    def set_developer_password(self, new_password: str) -> bool:
        """设置新的开发者密码"""
        salt, hash_val = self._hash_password(new_password)
        self._config.set('Security', 'developer_password_salt', salt)
        self._config.set('Security', 'developer_password_hash', hash_val)
        return self.save()
    
    def get(self, section: str, key: str, fallback: str = '') -> str:
        """获取配置项"""
        if self._config.has_section(section) and self._config.has_option(section, key):
            return self._config.get(section, key)
        return fallback
    
    def get_bool(self, section: str, key: str, fallback: bool = False) -> bool:
        """获取布尔配置项"""
        try:
            return self._config.getboolean(section, key)
        except:
            return fallback
    
    def set(self, section: str, key: str, value: str) -> None:
        """设置配置项"""
        if not self._config.has_section(section):
            self._config.add_section(section)
        self._config.set(section, key, value)
    
    def save(self) -> bool:
        """保存配置"""
        try:
            with open(self._config_file, 'w', encoding='utf-8') as f:
                self._config.write(f)
            return True
        except Exception as e:
            return False
    
    def get_all_ai_providers(self) -> Dict[str, Any]:
        """获取所有AI提供商配置"""
        try:
            providers_str = self.get('AI', 'providers', '{}')
            return json.loads(providers_str)
        except:
            return {}
    
    def set_ai_providers(self, providers: Dict[str, Any]) -> bool:
        """设置AI提供商配置"""
        self.set('AI', 'providers', json.dumps(providers))
        return self.save()

# 创建全局配置管理器实例
_config_manager = ConfigManager()
# ==================== 密码安全函数 ====================
class PasswordSecurity:
    @staticmethod
    def hash_password(password: str) -> Tuple[str, str]:
        """安全地哈希密码"""
        salt = secrets.token_hex(16)  # 32位随机盐
        # 使用PBKDF2加强哈希
        hash_obj = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000  # 迭代次数
        )
        return salt, hash_obj.hex()
    
    @staticmethod
    def verify_password(password: str, salt: str, stored_hash: str) -> bool:
        """验证密码"""
        try:
            hash_obj = hashlib.pbkdf2_hmac(
                'sha256',
                password.encode('utf-8'),
                salt.encode('utf-8'),
                100000
            )
            return hash_obj.hex() == stored_hash
        except:
            return False


