def _get_config_path() -> str:
    """获取国际化配置文件路径"""
    global _language_config_file
    if _language_config_file:
        return _language_config_file
    
    try:
        if getattr(sys, 'frozen', False):
            base_dir = os.path.dirname(sys.executable)
        elif '__file__' in globals():
            base_dir = os.path.dirname(os.path.abspath(__file__))
        else:
            base_dir = os.getcwd()
    except:
        base_dir = os.getcwd()
    
    _language_config_file = os.path.join(base_dir, 'i18n_config.json')
    return _language_config_file

def _load_config() -> Dict:
    """加载国际化配置"""
    global _current_language, _initialized
    
    config_path = _get_config_path()
    default_config = {"language": "auto", "fallback": "zh-CN"}
    
    try:
        if os.path.exists(config_path):
            with open(config_path, 'r', encoding='utf-8') as f:
                config = json.load(f)
                if "language" in config:
                    lang = config["language"]
                    if lang == "auto":
                        _current_language = _detect_system_language()
                    elif lang in SUPPORTED_LANGUAGES:
                        _current_language = lang
                    else:
                        _current_language = default_config["fallback"]
                if "fallback" in config and config["fallback"] in SUPPORTED_LANGUAGES:
                    global _fallback_language
                    _fallback_language = config["fallback"]
                _initialized = True
                return config
    except:
        pass
    
    _current_language = _detect_system_language()
    _fallback_language = default_config["fallback"]
    _initialized = True
    return default_config

def _save_config(config: Dict) -> bool:
    """保存国际化配置"""
    try:
        config_path = _get_config_path()
        with open(config_path, 'w', encoding='utf-8') as f:
            json.dump(config, f, ensure_ascii=False, indent=2)
        return True
    except:
        return False

def get_current_language() -> str:
    """获取当前语言"""
    global _current_language
    if not _initialized:
        _load_config()
    return _current_language

def set_language(lang_code: str) -> bool:
    """设置语言"""
    global _current_language
    
    if lang_code == "auto":
        _current_language = _detect_system_language()
    elif lang_code in SUPPORTED_LANGUAGES:
        _current_language = lang_code
    else:
        return False
    
    config = _load_config()
    config["language"] = lang_code
    return _save_config(config)

def translate(text: str) -> str:
    """翻译文本 - 支持在线翻译和本地缓存"""
    global _current_language, _fallback_language, _translator
    # 延迟预加载：首次调用时加载
    if not hasattr(_translator, '_preloaded'):
        preload_common_translations()
        _translator._preloaded = True
    if not _initialized:
        _load_config()
    
    # 如果当前语言是中文简体，直接返回原文
    if _current_language == "zh-CN":
        return text
    
    # 优先使用缓存翻译
    cached = _translator.cache.get(_current_language, text)
    if cached is not None:
        return cached
    
    # 精确匹配（使用在线翻译）
    if text in _BASE_TRANSLATIONS:
        trans_dict = _BASE_TRANSLATIONS[text]
        if _current_language in trans_dict:
            return trans_dict[_current_language]
        elif _fallback_language in trans_dict:
            return trans_dict[_fallback_language]
        elif "zh-CN" in trans_dict:
            return trans_dict["zh-CN"]
        else:
            # 尝试在线翻译
            result = _translator.translate(text, _current_language)
            if result != text:
                return result
            return text
    
    # ===== 改进的部分匹配（按长度降序，避免错误替换） =====
    # 按关键词长度降序排序，优先匹配最长的关键词
    sorted_keys = sorted(_BASE_TRANSLATIONS.keys(), key=len, reverse=True)
    for key in sorted_keys:
        if key in text and len(key) >= 2:
            # 检查是否是独立的词（边界检查），避免部分匹配错误
            trans_dict = _BASE_TRANSLATIONS[key]
            if _current_language in trans_dict:
                translated_word = trans_dict[_current_language]
                # 替换时保留大小写和前后空格
                return text.replace(key, translated_word)
            elif _fallback_language in trans_dict:
                return text.replace(key, trans_dict[_fallback_language])
    
    # 尝试在线翻译
    result = _translator.translate(text, _current_language)
    if result != text:
        return result
    
    return text

def init_language_system() -> None:
    """初始化语言系统（增强版）"""
    try:
        # 使用配置管理器获取语言设置
        config = ConfigManager()
        lang_setting = config.get('I18N', 'language', 'auto')
        
        if lang_setting == 'auto':
            detected_lang = _detect_system_language()
            _set_current_language(detected_lang)
        else:
            _set_current_language(lang_setting)
        
        # 初始化增强翻译系统
        global _translator
        if '_translator' not in globals():
            _translator = EnhancedTranslator()
        
        # 延迟预加载：移到首次使用时
        # preload_common_translations()  # 注释掉这行
        
        SystemLog.log(f"语言系统初始化完成: {get_current_language()}", "信息")
        SystemLog.log(f"翻译缓存目录: {_translator.cache.cache_dir}", "信息")
    except Exception as e:
        SystemLog.log(f"语言系统初始化失败: {str(e)}", "错误")

def _set_current_language(lang_code: str) -> None:
    """设置当前语言"""
    global _current_language
    if lang_code in SUPPORTED_LANGUAGES:
        _current_language = lang_code
    else:
        _current_language = 'zh-CN'


# ==================== 语言切换器类（开发者功能） ====================

class LanguageSwitcher:
    """语言切换器 - 开发者专用功能"""
    
    # ========== 新增：翻译缓存系统 ==========
    _translation_cache = {}  # 类级缓存
    _cache_lock = threading.Lock()
    
    @staticmethod
    def _update_translation_cache(lang_code: str) -> None:
        """
        更新翻译缓存
        
        功能：
        1. 预加载当前语言的所有翻译到内存缓存
        2. 提高翻译查询性能（避免每次都遍历字典）
        3. 支持多语言切换时的缓存更新
        
        参数:
            lang_code: 语言代码 (如 'zh-CN', 'en-US')
        """
        import time
        
        # 如果语言代码无效，使用备用语言
        if lang_code not in SUPPORTED_LANGUAGES:
            lang_code = _fallback_language
        
        # 如果语言代码是 "auto"，检测系统语言
        if lang_code == "auto":
            lang_code = _detect_system_language()
        
        # 防止缓存被多个线程同时修改
        with LanguageSwitcher._cache_lock:
            # 如果已经是当前语言，跳过重建
            if lang_code in LanguageSwitcher._translation_cache:
                safe_print(f"✅ 翻译缓存已存在: {lang_code}")
                return
            
            safe_print(f"🔄 正在构建翻译缓存: {lang_code}...")
            start_time = time.time()
            
            # 构建新的缓存字典
            new_cache = {}
            
            # 遍历基础翻译词库
            for key, trans_dict in _BASE_TRANSLATIONS.items():
                # 优先使用目标语言
                if lang_code in trans_dict:
                    new_cache[key] = trans_dict[lang_code]
                # 回退到备用语言
                elif _fallback_language in trans_dict:
                    new_cache[key] = trans_dict[_fallback_language]
                # 最后回退到简体中文
                elif "zh-CN" in trans_dict:
                    new_cache[key] = trans_dict["zh-CN"]
                else:
                    # 如果都没有，保留原文
                    new_cache[key] = key
            
            # 保存缓存
            LanguageSwitcher._translation_cache[lang_code] = new_cache
            
            elapsed_ms = (time.time() - start_time) * 1000
            cache_size = len(new_cache)
            safe_print(f"✅ 翻译缓存构建完成: {cache_size} 条条目, {elapsed_ms:.2f}ms")
            
            # 记录日志（如果 SystemLog 已初始化）
            try:
                SystemLog.log(f"翻译缓存已构建: {lang_code} ({cache_size} 条)", "信息")
            except:
                pass
    
    @staticmethod
    def _get_cached_translation(text: str) -> Optional[str]:
        """
        从缓存中获取翻译（快速路径）
        
        参数:
            text: 要翻译的文本
        
        返回:
            翻译后的文本，如果缓存中不存在则返回 None
        """
        current_lang = get_current_language()
        
        # 如果是中文，直接返回原文（无需翻译）
        if current_lang == "zh-CN":
            return text
        
        # 获取缓存
        cache = LanguageSwitcher._translation_cache.get(current_lang)
        if cache is None:
            # 缓存不存在，尝试构建
            LanguageSwitcher._update_translation_cache(current_lang)
            cache = LanguageSwitcher._translation_cache.get(current_lang)
            if cache is None:
                return None
        
        # 精确匹配
        if text in cache:
            return cache[text]
        
        # 部分匹配（用于组合文本）
        for key, translated in cache.items():
            if key in text and len(key) >= 2:
                return text.replace(key, translated)
        
        return None
    
    @staticmethod
    def clear_translation_cache(lang_code: Optional[str] = None, silent: bool = False) -> None:
        """清除翻译缓存"""
        if not silent and lang_code is None:
            lang = get_current_language()
            confirm = input(f"确定要清除 {lang} 的翻译缓存吗? (Y/N): ").strip().upper()
            if confirm != 'Y':
                safe_print("已取消")
                return
            _translator.clear_cache(lang)
            safe_print(f"✅ 已清除 {lang} 的翻译缓存")
        else:
            with LanguageSwitcher._cache_lock:
                if lang_code is None:
                    LanguageSwitcher._translation_cache.clear()
                    safe_print("✅ 所有翻译缓存已清除")
                elif lang_code in LanguageSwitcher._translation_cache:
                    del LanguageSwitcher._translation_cache[lang_code]
                    safe_print(f"✅ 翻译缓存已清除: {lang_code}")
                else:
                    safe_print(f"⚠️ 缓存不存在: {lang_code}")

    
    @staticmethod
    def get_cache_stats() -> Dict[str, Any]:
        """
        获取缓存统计信息（开发者调试用）
        
        返回:
            包含缓存大小和语言列表的字典
        """
        with LanguageSwitcher._cache_lock:
            return {
                "cached_languages": list(LanguageSwitcher._translation_cache.keys()),
                "total_cache_count": len(LanguageSwitcher._translation_cache),
                "cache_size_per_lang": {
                    lang: len(cache) 
                    for lang, cache in LanguageSwitcher._translation_cache.items()
                }
            }
