    @staticmethod
    def switch_language() -> None:
        """执行语言切换"""
        while True:
            LanguageSwitcher.show_language_switch_menu()
            
            choice = input("\n请选择语言编号 (或输入语言名称): ").strip()
            
            if choice.lower() == 'q':
                safe_print("已取消语言切换")
                return
            
            target_lang = None
            
            # 检查编号
            if choice.isdigit():
                idx = int(choice)
                if idx == 0:
                    target_lang = "auto"
                else:
                    languages = list(SUPPORTED_LANGUAGES.keys())
                    if 1 <= idx <= len(languages):
                        target_lang = languages[idx - 1]
            else:
                # 匹配语言名称
                for code, name in SUPPORTED_LANGUAGES.items():
                    if choice.lower() in name.lower() or choice.lower() in code.lower():
                        target_lang = code
                        break
            
            if target_lang is None:
                safe_print("❌ 无效选择，请重新输入")
                continue
            
            LanguageSwitcher._do_switch_language(target_lang)
            return
