# ==================== 智能加密降级系统 ====================

class NativeCrypto:
    """
    Python 原生加密实现（无第三方依赖）
    功能：提供基本的加密/解密能力，作为 cryptography 的降级方案
    """
    
    @staticmethod
    def simple_encrypt(data: bytes, key: str) -> bytes:
        """使用 Python 原生库进行简单加密"""
        import base64
        import hashlib
        
        key_bytes = hashlib.sha256(key.encode()).digest()
        
        encrypted = bytearray()
        for i, byte in enumerate(data):
            encrypted.append(byte ^ key_bytes[i % len(key_bytes)])
        
        return base64.b64encode(bytes(encrypted))
    
    @staticmethod
    def simple_decrypt(encrypted_data: bytes, key: str) -> bytes:
        """使用 Python 原生库进行简单解密"""
        import base64
        import hashlib
        
        try:
            encrypted = base64.b64decode(encrypted_data)
            key_bytes = hashlib.sha256(key.encode()).digest()
            
            decrypted = bytearray()
            for i, byte in enumerate(encrypted):
                decrypted.append(byte ^ key_bytes[i % len(key_bytes)])
            
            return bytes(decrypted)
        except:
            return b''
    
    @staticmethod
    def get_encryption_key() -> bytes:
        """生成加密密钥（基于机器特征）"""
        import hashlib
        import platform
        import os
        
        machine_id = (
            platform.node() + 
            os.environ.get('COMPUTERNAME', '') +
            os.environ.get('USERNAME', '') +
            platform.processor() or ''
        ).encode()
        
        return hashlib.sha256(machine_id).digest()


class SmartCrypto:
    """
    智能加密管理器
    自动选择最优加密方案，并提供统一接口
    """
    
    _use_native = False
    _crypto_available = False
    _initialized = False
    
    @classmethod
    def init(cls) -> bool:
        """初始化加密系统"""
        if cls._initialized:
            return True
        
        try:
            from cryptography.fernet import Fernet
            cls._crypto_available = True
            cls._use_native = False
            cls._initialized = True
            return True
        except ImportError:
            pass
        
        # 降级到原生方案
        cls._crypto_available = True
        cls._use_native = True
        cls._initialized = True
        return True
    
    @classmethod
    def encrypt_bytes(cls, data: bytes) -> bytes:
        """加密数据"""
        if not cls._initialized:
            cls.init()
        
        if not cls._crypto_available:
            raise RuntimeError("加密系统未初始化")
        
        if cls._use_native:
            key = NativeCrypto.get_encryption_key()
            return NativeCrypto.simple_encrypt(data, key.hex())
        else:
            from cryptography.fernet import Fernet
            key = DataEncryption.get_encryption_key()
            fernet = Fernet(key)
            return fernet.encrypt(data)
    
    @classmethod
    def decrypt_bytes(cls, encrypted_data: bytes) -> bytes:
        """解密数据"""
        if not cls._initialized:
            cls.init()
        
        if not cls._crypto_available:
            raise RuntimeError("加密系统未初始化")
        
        if cls._use_native:
            key = NativeCrypto.get_encryption_key()
            return NativeCrypto.simple_decrypt(encrypted_data, key.hex())
        else:
            from cryptography.fernet import Fernet
            key = DataEncryption.get_encryption_key()
            fernet = Fernet(key)
            return fernet.decrypt(encrypted_data)
    
    @classmethod
    def is_using_native(cls) -> bool:
        """是否使用原生库"""
        return cls._use_native
    
    @classmethod
    def get_status(cls) -> Dict[str, Any]:
        """获取加密状态"""
        return {
            "available": cls._crypto_available,
            "using_native": cls._use_native,
            "crypto_library": "原生 (Python)" if cls._use_native else "cryptography"
        }


def init_crypto_system() -> bool:
    """
    启动时初始化加密系统
    1. 尝试加载 cryptography
    2. 如果失败，尝试安装
    3. 如果无网络，降级到原生方案
    """
    try:
        import cryptography
        SmartCrypto._crypto_available = True
        SmartCrypto._use_native = False
        SmartCrypto._initialized = True
        safe_print("✅ 使用 cryptography 库（高性能加密）")
        return True
    except ImportError:
        safe_print("⚠️  cryptography 库未安装，尝试自动安装...")
        
        try:
            import subprocess
            result = subprocess.run(
                [sys.executable, "-m", "pip", "install", "cryptography", "--quiet", "--no-input"],
                capture_output=True,
                timeout=60
            )
            if result.returncode == 0:
                import cryptography
                SmartCrypto._crypto_available = True
                SmartCrypto._use_native = False
                SmartCrypto._initialized = True
                safe_print("✅ cryptography 安装成功，使用高性能加密")
                return True
        except:
            pass
        
        # 安装失败或无网络，降级到原生
        SmartCrypto.init()
        safe_print("🔒 使用 Python 原生加密（无第三方依赖，功能完整）")
        safe_print("💡 如需高性能加密，请手动安装: pip install cryptography")
        return True
# ==================== 四层加密防护系统 ====================

class QuadLayerEncryption:
    """四层加密防护系统"""

    PBKDF2_ITERATIONS = 100000

    @staticmethod
    def get_machine_binding_status() -> bool:
        """获取机器码绑定状态"""
        try:
            config = ConfigManager()
            status = config.get('Security', 'machine_binding', 'true')
            return status.lower() in ('true', '1', 'yes', 'on')
        except:
            return True

    @staticmethod
    def set_machine_binding_status(enabled: bool) -> bool:
        """设置机器码绑定状态"""
        try:
            config = ConfigManager()
            config.set('Security', 'machine_binding', str(enabled).lower())
            return config.save()
        except:
            return False

    @staticmethod
    def get_machine_unique_id() -> bytes:
        """获取机器唯一特征码"""
        # 检查是否禁用了机器码绑定
        if not QuadLayerEncryption.get_machine_binding_status():
            # 使用固定哈希（用于开发调试）
            return hashlib.sha256(b"PWOS5_DEV_MODE_FIXED_2024").digest()

        import subprocess
        import platform
        
        machine_id = ""
        
        if platform.system() == "Windows":
            try:
                result = subprocess.run(
                    ['wmic', 'baseboard', 'get', 'serialnumber'],
                    capture_output=True, text=True, timeout=5
                )
                board_sn = result.stdout.strip().split('\n')[-1].strip()
                if board_sn and 'To be filled' not in board_sn:
                    machine_id += board_sn
            except:
                pass
            
            try:
                result = subprocess.run(
                    ['wmic', 'diskdrive', 'get', 'serialnumber'],
                    capture_output=True, text=True, timeout=5
                )
                disk_sn = result.stdout.strip().split('\n')[-1].strip()
                if disk_sn and disk_sn != 'SerialNumber':
                    machine_id += disk_sn
            except:
                pass
        
        machine_id += platform.processor() or ""
        machine_id += platform.node() or ""
        machine_id += os.environ.get('COMPUTERNAME', '')
        machine_id += os.environ.get('USERNAME', '')
        
        if len(machine_id) < 32:
            machine_id = machine_id.ljust(32, 'X')
        else:
            machine_id = machine_id[:32]
        
        return machine_id.encode('utf-8')

    @staticmethod
    def generate_random_key(length: int = 32) -> str:
        """第一关：生成高强度随机密钥"""
        uppercase = 'ABCDEFGHJKLMNPQRSTUVWXYZ'
        lowercase = 'abcdefghijkmnopqrstuvwxyz'
        digits = '23456789'
        symbols = '#$%&@?'
        
        key_chars = [
            secrets.choice(uppercase),
            secrets.choice(lowercase),
            secrets.choice(digits),
            secrets.choice(symbols),
        ]
        
        all_chars = uppercase + lowercase + digits + symbols
        for _ in range(length - 4):
            key_chars.append(secrets.choice(all_chars))
        
        secrets.SystemRandom().shuffle(key_chars)
        return ''.join(key_chars)

    @staticmethod
    def double_pbkdf2_hash(password: str) -> Tuple[bytes, bytes, bytes, bytes]:
        """第二关：双层 PBKDF2 哈希（纯内置库版本）"""
        import hashlib
        
        salt1 = secrets.token_bytes(32)
        salt2 = secrets.token_bytes(32)
        
        hash1 = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt1,
            QuadLayerEncryption.PBKDF2_ITERATIONS,
            dklen=32
        )
        
        hash2 = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt2,
            QuadLayerEncryption.PBKDF2_ITERATIONS,
            dklen=32
        )
        
        return hash1, salt1, hash2, salt2

    @staticmethod
    def xor_mix(hash1: bytes, hash2: bytes, machine_id: bytes) -> bytes:
        """第四关：异或混合"""
        length = max(len(hash1), len(hash2), len(machine_id))
        
        h1 = hash1.ljust(length, b'\x00')
        h2 = hash2.ljust(length, b'\x00')
        mid = machine_id.ljust(length, b'\x00')
        
        result = bytes(h1[i] ^ h2[i] ^ mid[i] for i in range(length))
        return result[:32]

    @staticmethod
    def create_encrypted_key() -> Tuple[bytes, dict]:
        """创建四层加密的最终密钥"""
        raw_key = QuadLayerEncryption.generate_random_key(32)
        hash1, salt1, hash2, salt2 = QuadLayerEncryption.double_pbkdf2_hash(raw_key)
        machine_id = QuadLayerEncryption.get_machine_unique_id()
        final_key = QuadLayerEncryption.xor_mix(hash1, hash2, machine_id)
        
        metadata = {
            'salt1': base64.b64encode(salt1).decode(),
            'salt2': base64.b64encode(salt2).decode(),
            'hash1': base64.b64encode(hash1).decode(),
            'hash2': base64.b64encode(hash2).decode(),
            'machine_id_hash': hashlib.sha256(machine_id).hexdigest(),
            'pbkdf2_iterations': QuadLayerEncryption.PBKDF2_ITERATIONS,
        }
        
        return final_key, metadata


class SecureKeyFile:
    """安全的密钥文件存储 (.pwos 格式)"""

    @staticmethod
    def save_key(key: bytes, metadata: dict, filepath: Path) -> bool:
        MAGIC = b'PWKS'
        VERSION = 1
        
        metadata_bytes = json.dumps(metadata, ensure_ascii=False).encode('utf-8')
        
        with open(filepath, 'wb') as f:
            f.write(MAGIC)
            f.write(struct.pack('B', VERSION))
            f.write(struct.pack('>H', len(key)))
            f.write(key)
            f.write(struct.pack('>I', len(metadata_bytes)))
            f.write(metadata_bytes)
        
        if sys.platform == 'win32':
            try:
                import ctypes
                ctypes.windll.kernel32.SetFileAttributesW(str(filepath), 2)
            except:
                pass
        
        return True

    @staticmethod
    def load_key(filepath: Path) -> Tuple[Optional[bytes], Optional[dict]]:
        if not filepath.exists():
            return None, None
        
        try:
            with open(filepath, 'rb') as f:
                magic = f.read(4)
                if magic != b'PWKS':
                    return None, None
                
                version = struct.unpack('B', f.read(1))[0]
                if version != 1:
                    return None, None
                
                key_len = struct.unpack('>H', f.read(2))[0]
                key = f.read(key_len)
                
                metadata_len = struct.unpack('>I', f.read(4))[0]
                metadata_bytes = f.read(metadata_len)
                metadata = json.loads(metadata_bytes.decode('utf-8'))
                
                return key, metadata
        except Exception:
            return None, None


class DataEncryption:
    """数据加密管理器 - 整合四层加密"""

    @staticmethod
    def _get_key_file() -> Path:
        """获取密钥文件路径（程序目录）"""
        if getattr(sys, 'frozen', False):
            base_dir = Path(sys.executable).parent
        else:
            base_dir = Path(__file__).parent
        
        data_dir = base_dir / 'user_system_data'
        data_dir.mkdir(parents=True, exist_ok=True)
        return data_dir / 'pwos_data.key'

    @staticmethod
    def get_encryption_key() -> bytes:
        """获取加密密钥（返回 base64 格式）"""
        # 如果使用原生加密方案
        if SmartCrypto.is_using_native():
            key = NativeCrypto.get_encryption_key()
            import base64
            return base64.urlsafe_b64encode(key)
        
        # 否则使用原有的四层加密
        from cryptography.fernet import Fernet
        import base64
        import hashlib
        
        key_file = DataEncryption._get_key_file()
        
        if key_file.exists():
            # 检查是否需要重新生成（机器码绑定状态改变）
            need_regenerate = False
            
            # 检查密钥长度是否有效
            try:
                with open(key_file, 'rb') as f:
                    raw_key = f.read()
                if len(raw_key) != 32:
                    need_regenerate = True
            except:
                need_regenerate = True
            
            if not need_regenerate:
                # 检查机器码绑定状态是否改变
                binding_status_file = key_file.parent / 'binding_status.txt'
                current_binding = QuadLayerEncryption.get_machine_binding_status()
                if binding_status_file.exists():
                    try:
                        with open(binding_status_file, 'r') as f:
                            saved_binding = f.read().strip() == 'True'
                        if saved_binding != current_binding:
                            need_regenerate = True
                    except:
                        need_regenerate = True
                else:
                    need_regenerate = True
            
            if not need_regenerate:
                if len(raw_key) != 32:
                    raw_key = hashlib.sha256(raw_key).digest()
                    with open(key_file, 'wb') as f:
                        f.write(raw_key)
                return base64.urlsafe_b64encode(raw_key)
            
            # 需要重新生成，删除旧密钥
            try:
                key_file.unlink()
            except:
                pass
        
        # 生成新密钥
        final_key, metadata = QuadLayerEncryption.create_encrypted_key()
        
        if len(final_key) != 32:
            final_key = hashlib.sha256(final_key).digest()
        
        key_file.parent.mkdir(parents=True, exist_ok=True)
        with open(key_file, 'wb') as f:
            f.write(final_key)
        
        # 保存绑定状态
        binding_status_file = key_file.parent / 'binding_status.txt'
        with open(binding_status_file, 'w') as f:
            f.write(str(QuadLayerEncryption.get_machine_binding_status()))
        
        fernet_key = base64.urlsafe_b64encode(final_key)
        return fernet_key

    @staticmethod
    def encrypt_bytes(data: bytes) -> bytes:
        """加密字节数据"""
        return SmartCrypto.encrypt_bytes(data)

    @staticmethod
    def decrypt_bytes(encrypted: bytes) -> bytes:
        """解密字节数据"""
        return SmartCrypto.decrypt_bytes(encrypted)

    @staticmethod
    def encrypt_file(filepath: Path) -> bool:
        """加密文件"""
        if not filepath.exists():
            return False
        
        try:
            with open(filepath, 'rb') as f:
                data = f.read()
            
            encrypted = DataEncryption.encrypt_bytes(data)
            
            with open(filepath, 'wb') as f:
                f.write(encrypted)
            
            return True
        except Exception:
            return False

    @staticmethod
    def decrypt_file(filepath: Path) -> Optional[bytes]:
        """解密文件"""
        if not filepath.exists():
            return None
        
        try:
            with open(filepath, 'rb') as f:
                encrypted = f.read()
            
            return DataEncryption.decrypt_bytes(encrypted)
        except Exception:
            return None

    @staticmethod
    def read_json(filepath: Path):
        """读取加密的 JSON 文件"""
        decrypted = DataEncryption.decrypt_file(filepath)
        if decrypted is None:
            return None
        return json.loads(decrypted.decode('utf-8'))

    @staticmethod
    def write_json(filepath: Path, data) -> bool:
        """写入加密的 JSON 文件"""
        json_str = json.dumps(data, ensure_ascii=False, indent=2)
        encrypted = DataEncryption.encrypt_bytes(json_str.encode('utf-8'))
        
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, 'wb') as f:
            f.write(encrypted)
        
        return True

class DataManagement:
    
    # ==================== 路径管理 ====================
    
    @staticmethod
    def _get_encrypted_data_dir() -> Path:
        """获取加密数据存储目录（直接使用原 user_system_data 目录）"""
        base_dir = DataManagement._get_base_dir()
        return base_dir / 'user_system_data'

    @staticmethod
    def _get_base_dir() -> Path:
        """程序所在目录"""
        if getattr(sys, 'frozen', False):
            return Path(sys.executable).parent
        return Path(__file__).parent

    
    # ==================== 初始化 ====================
    
    @staticmethod
    def init_system() -> bool:
        """初始化系统（加密版，完整功能）"""
        try:
            # 加密数据目录（C盘）
            encrypted_dir = DataManagement._get_encrypted_data_dir()
            backup_dir = encrypted_dir / 'backups'
            user_files_dir = encrypted_dir / 'user_files'
            
            # 批量创建目录
            for d in [encrypted_dir, backup_dir, user_files_dir]:
                d.mkdir(parents=True, exist_ok=True)
            
            # 脚本和更新包目录（程序目录明文存储）
            base_dir = DataManagement._get_base_dir()
            for d in [base_dir / 'scripts', base_dir / 'update_packages']:
                d.mkdir(parents=True, exist_ok=True)
            
            # 批量初始化配置文件（只在文件不存在时创建）
            files_to_init = {
                encrypted_dir / 'occupations.json': ["学生", "教师", "工程师", "医生", "护士", "程序员", "设计师", "销售", "经理", "厨师", "司机", "公务员", "农民", "自由职业", "其他"],
                encrypted_dir / 'secure_passwords.json': [],
                encrypted_dir / 'version.json': {"major": 3, "minor": 0},
                encrypted_dir / 'firewall_rules.json': {
                    "enable_firewall": False,
                    "block_weak_passwords": True,
                    "max_login_attempts": 5,
                    "session_timeout": 1800,
                    "audit_logging": True
                },
                encrypted_dir / 'ai_config.json': {
                    "enable_ai": False,
                    "providers": {
                        "deepseek": {"enabled": False, "api_key": "", "api_base": "https://api.deepseek.com", "model": "deepseek-chat"},
                        "aliyun": {"enabled": False, "api_key": "", "api_base": "https://dashscope.aliyuncs.com", "model": "qwen-max"}
                    },
                    "last_provider": "deepseek",
                    "temperature": 0.7,
                    "max_tokens": 1000
                },
                encrypted_dir / 'network_rules.json': {"blacklist": [], "whitelist": [], "description": "网络防火墙规则"},
                user_files_dir / 'default.json': {"users": {}, "next_id": 1, "empty_ids": []},
            }
            
            for filepath, default_data in files_to_init.items():
                if not filepath.exists():
                    DataEncryption.write_json(filepath, default_data)
            
            # 确保 emoji 配置文件存在
            config_file = os.path.join(_BASE_DIR, 'emoji_config.json')
            if not os.path.exists(config_file):
                with open(config_file, 'w', encoding='utf-8') as f:
                    json.dump({"emoji_mode": "A"}, f)
            
            # 初始化分组系统
            UserGroupManager.init_group_system()
            SystemLog.log("加密系统初始化完成")
            return True
            
        except Exception as e:
            SystemLog.log(f"初始化系统失败: {str(e)}", "错误")
            return False
    
    # ==================== 密码管理 ====================
    
    @staticmethod
    def load_secure_passwords() -> List[Tuple[str, str]]:
        """加载安全的密码列表（从加密文件）"""
        try:
            encrypted_dir = DataManagement._get_encrypted_data_dir()
            password_file = encrypted_dir / 'secure_passwords.json'
            
            if password_file.exists():
                passwords_data = DataEncryption.read_json(password_file)
                if passwords_data and isinstance(passwords_data, list):
                    if len(passwords_data) > 0 and isinstance(passwords_data[0], dict):
                        return [(p["salt"], p["hash"]) for p in passwords_data]
            return []
        except Exception:
            return []

    @staticmethod
    def save_secure_passwords(passwords: List[Tuple[str, str]]) -> bool:
        """保存安全的密码列表（加密存储）"""
        try:
            encrypted_dir = DataManagement._get_encrypted_data_dir()
            password_file = encrypted_dir / 'secure_passwords.json'
            passwords_data = [{"salt": salt, "hash": pwd_hash} for salt, pwd_hash in passwords]
            return DataEncryption.write_json(password_file, passwords_data)
        except Exception:
            return False

